public void insert()
{
    NumberSeq journalNum;

    ttsbegin;

    if (!this.JournalNum)
    {
        journalNum      = NumberSeq::newGetNum(UPSParameters::numRefVendPriceJournalNum());
        this.JournalNum = journalNum.num();
    }

    super();

    ttscommit;
}

public void defaultField(FieldId _fieldId)
{
    super(_fieldId);

    switch (_fieldId)
    {
        case fieldnum(UPSVendPriceAdmTable, Name):
            this.defaultName();
            break;

        case fieldnum(UPSVendPriceAdmTable, DefaultRelation):
            this.defaultRelation();
            break;
    }
}

private void defaultName()
{
    if (this.JournalName)
    {
        UPSVendPriceAdmName vendPriceAdmName = UPSVendPriceAdmName::find(this.JournalName);
        this.Name = vendPriceAdmName.Name;
    }
    else
    {
        this.Name = "";
    }
}

private void defaultRelation()
{
    if (this.JournalName)
    {
        UPSVendPriceAdmName vendPriceAdmName = UPSVendPriceAdmName::find(this.JournalName);
        this.DefaultRelation = vendPriceAdmName.DefaultRelation;
    }
    else
    {
        this.DefaultRelation = UPSVendPriceType::PriceVendList;
    }
}

public boolean validateWrite()
{
    boolean ret;
    NumberSeq journalNum;

    ttsbegin;

    if (!this.JournalNum && this.JournalName)
    {
        journalNum      = NumberSeq::newGetNum(UPSParameters::numRefVendPriceJournalNum());
        this.JournalNum = journalNum.num();
    }

    ret = super();

    ttscommit;

    return ret;
}

public container getDefaultingDependencies()
{
    return [
             [fieldnum(UPSVendPriceAdmTable, Name), [fieldnum(UPSVendPriceAdmTable, JournalName)]],
             [fieldnum(UPSVendPriceAdmTable, DefaultRelation), [fieldnum(UPSVendPriceAdmTable, JournalName)]]
    ];
}

public static UPSVendPriceAdmTable find(UPSVendPriceJournalNum _journalNum, boolean _forupdate = false)
{
    UPSVendPriceAdmTable UPSVendPriceAdmTable;

    if (_journalNum)
    {
        UPSVendPriceAdmTable.selectForUpdate(_forupdate);

        select firstonly UPSVendPriceAdmTable
            index hint JournalNumIdx
            where UPSVendPriceAdmTable.JournalNum == _journalNum;
    }

    return UPSVendPriceAdmTable;
}

public boolean canUpdateLines(boolean _showWarning = false)
{
    boolean canUpdate = true;
    str warningMessage;

    if (this.Posted == NoYes::Yes)
    {
        warningMessage = strFmt("@SYS18421", this.JournalNum);
        canUpdate = false;
    }

    if (warningMessage && _showWarning)
    {
        warning(warningMessage);
    }

    return canUpdate;
}
